lock table public.world_quest_steps in share row exclusive mode;
update public.world_quest_steps set lines = jsonb_set(lines, '{4,t}', to_jsonb(replace(lines -> 4 ->> 't', '/*=', '/혈기=조사원 도끼로 다 찍어 버려!/여명=조사원 창으로 다 꿰어 버려!/진법=조사원 산가지로 갈대를 묶어 버려!/*='))) where quest_id = 'cq110_bat_2' and step = 2 and lines -> 4 ->> 't' like '%{직업:%' and lines -> 4 ->> 't' not like '%혈기=%';
