update public.world_quest_steps set lines = jsonb_insert(lines, '{9}', jsonb_build_object('s', 'q:m_yeon', 'job', 'formation', 't', '진법가군요. 다치기 전에 막아 준다고 들었어요. 서고 사람들 곁에 진 하나 쳐 주면 좋겠어요.'), true) where quest_id = 'mq_red_seal' and step = 1 and lines -> 9 ->> 'job' = 'tamer' and not exists (select 1 from jsonb_array_elements(lines) e where e ->> 'job' = 'formation');
update public.world_quest_steps set lines = jsonb_insert(lines, '{9}', jsonb_build_object('s', 'q:m_yeon', 'job', 'spearman', 't', '여명 창객이군요. 긴 창이면 서고 복도 끝까지 닿겠어요. 앞은 맡길게요.'), true) where quest_id = 'mq_red_seal' and step = 1 and lines -> 9 ->> 'job' = 'tamer' and not exists (select 1 from jsonb_array_elements(lines) e where e ->> 'job' = 'spearman');
update public.world_quest_steps set lines = jsonb_insert(lines, '{9}', jsonb_build_object('s', 'q:m_yeon', 'job', 'bloodknight', 't', '혈기사군요. 피 냄새를 맡고 덤비는 것들이 있으면 앞에 서 줘요. 다치면 바로 말하고요.'), true) where quest_id = 'mq_red_seal' and step = 1 and lines -> 9 ->> 'job' = 'tamer' and not exists (select 1 from jsonb_array_elements(lines) e where e ->> 'job' = 'bloodknight');
